/*
 * "Is my Mazda supported?" checker for docs/getting-started/
 * supported-cars.md.
 *
 * Data comes from window.ZP_CARS
 * (docs/assets/js/car-checker-data.js), generated by the site repo's
 * sync script from the same source the main site's checker uses, so
 * both always agree. The questions mirror what the wiki documents:
 * model family first, then — for older Mazdas — the steering motor,
 * because that is what support actually keys on.
 */
(function () {
  "use strict";

  var mount = document.getElementById("zp-car-checker");
  var cars = window.ZP_CARS;
  if (!mount || !cars) return;

  mount.innerHTML = "";
  mount.className = "zp-checker";

  function option(value, label) {
    var o = document.createElement("option");
    o.value = value;
    o.textContent = label;
    return o;
  }

  var form = document.createElement("div");
  form.className = "zp-checker-form";

  var labelCar = document.createElement("label");
  labelCar.textContent = "Which Mazda?";
  var car = document.createElement("select");
  car.appendChild(option("", "Choose…"));
  car.appendChild(option("cx5", "CX-5, 2022–2025"));
  car.appendChild(option("cx9", "CX-9, 2021–2023"));
  car.appendChild(option("older", "An older Mazda"));
  labelCar.appendChild(car);

  var labelMotor = document.createElement("label");
  labelMotor.textContent = "Steering motor?";
  labelMotor.hidden = true;
  var motor = document.createElement("select");
  motor.appendChild(option("", "Choose…"));
  motor.appendChild(option("stock", "Original, never swapped"));
  motor.appendChild(option("swap", "2022–25 CX-5 motor swapped in"));
  motor.appendChild(option("unsure", "Not sure"));
  labelMotor.appendChild(motor);

  form.appendChild(labelCar);
  form.appendChild(labelMotor);
  mount.appendChild(form);

  var out = document.createElement("div");
  out.className = "zp-checker-out";
  out.setAttribute("role", "status");
  mount.appendChild(out);

  function verdict(title, body, good) {
    out.innerHTML = "";
    var t = document.createElement("strong");
    t.textContent = title;
    if (good === true) t.classList.add("is-good");
    if (good === false) t.classList.add("is-bad");
    var p = document.createElement("p");
    /* body may carry one {{EPS_SWAP}} placeholder for the eps-swap
     * page link; this page and eps-swap are siblings, and the wiki
     * builds with directory URLs, so the relative link is the page
     * directory name */
    p.innerHTML = body.replace(
      /\{\{EPS_SWAP\}\}/g,
      '<a href="eps-swap/">the EPS swap</a>',
    );
    out.appendChild(t);
    out.appendChild(p);
    out.hidden = false;
  }

  var rowFor = function (needle) {
    var found = null;
    cars.forEach(function (c) {
      if (c.car.toLowerCase().indexOf(needle) !== -1) found = c;
    });
    return found;
  };

  function renderMotor() {
    labelMotor.hidden = car.value !== "older";
    if (car.value !== "older") return;
    if (motor.value === "swap") {
      verdict(
        "Supported — the swap is what does it.",
        rowFor("swapped")
          ? rowFor("swapped").notes
          : "The 2022-25 CX-5 EPS motor identifies by firmware, steering works down to 0 mph, and alpha longitudinal is enabled.",
        true,
      );
    } else if (motor.value === "stock") {
      verdict(
        "Not yet.",
        "zoompilot's steering work keys on the 2022-25 CX-5 EPS motor. An original older motor stays out of scope — this is exactly what {{EPS_SWAP}} is for.",
        false,
      );
    } else if (motor.value === "unsure") {
      verdict(
        "Check the motor first.",
        "Support depends on which steering motor the car has, not just the model year. {{EPS_SWAP}} explains what to look for, or ask on the Discord with your model year.",
      );
    } else {
      out.hidden = true;
    }
  }

  motor.addEventListener("change", renderMotor);
  car.addEventListener("change", function () {
    out.hidden = true;
    motor.value = "";
    renderMotor();
    if (car.value === "cx5") {
      verdict(
        "Supported — this is the primary target.",
        rowFor("CX-5 2022")
          ? rowFor("CX-5 2022").notes
          : "Every zoompilot feature. Steering works down to 0 mph.",
        true,
      );
    } else if (car.value === "cx9") {
      verdict(
        "Supported.",
        rowFor("CX-9")
          ? rowFor("CX-9").notes
          : "Factory-matched specs included. Speed-dependent torque needs more learning time, because the starting seeds come from a CX-5.",
        true,
      );
    } else if (car.value === "older") {
      renderMotor();
    } else {
      out.hidden = true;
      out.innerHTML = "";
    }
  });
})();
